<?php
require_once __DIR__.'/../includes/account.php'; account_schema();
$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$name=trim($_POST['full_name']??'');$email=strtolower(trim($_POST['email']??''));$phone=trim($_POST['phone']??'');$type=$_POST['account_type']??'customer';$pass=$_POST['password']??'';$confirm=$_POST['confirm_password']??'';
 if($name==='')$errors[]='Enter your full name.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email address.';if(!in_array($type,['business','talent','student','customer'],true))$errors[]='Choose a valid account type.';if(strlen($pass)<8)$errors[]='Password must contain at least 8 characters.';if($pass!==$confirm)$errors[]='Passwords do not match.';
 if(!$errors){try{$st=db()->prepare('INSERT INTO user_accounts(full_name,email,phone,password,account_type) VALUES(?,?,?,?,?)');$st->execute([$name,$email,$phone,password_hash($pass,PASSWORD_DEFAULT),$type]);$id=(int)db()->lastInsertId();session_regenerate_id(true);$_SESSION['user_id']=$id;account_log($id,'Created account');header('Location: dashboard.php');exit;}catch(PDOException $e){$errors[]=$e->getCode()==='23000'?'An account with this email already exists.':'Registration failed. Please try again.';}}
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create account | Plateau Digital</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="form-shell"><a href="../index.php">← Plateau Digital</a><h1>Create your account</h1><p>One account gives you access to the Plateau Digital ecosystem.</p><?php foreach($errors as $x):?><div class="submit-error"><?=e($x)?></div><?php endforeach;?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="form-field"><label>Full name *</label><input name="full_name" required value="<?=e($_POST['full_name']??'')?>"></div><div class="form-field"><label>Email *</label><input type="email" name="email" required value="<?=e($_POST['email']??'')?>"></div><div class="form-field"><label>Phone</label><input name="phone" value="<?=e($_POST['phone']??'')?>"></div><div class="form-field"><label>Account type *</label><select name="account_type"><option value="customer">Customer / Visitor</option><option value="business">Business owner</option><option value="talent">Professional / Talent</option><option value="student">Student</option></select></div><div class="form-field"><label>Password *</label><input type="password" name="password" minlength="8" required></div><div class="form-field"><label>Confirm password *</label><input type="password" name="confirm_password" minlength="8" required></div></div><button class="btn" type="submit">Create account</button></form><p>Already registered? <a href="login.php">Sign in</a></p></main></body></html>
